class SagaExecutionError(RuntimeError):
    def __init__(self, step, original_error, compensated_steps):
        super().__init__(f"Saga failed at step '{step}': {original_error}")
        self.failed_step = step
        self.original_error = original_error
        self.compensated_steps = compensated_steps

class SagaCoordinator:
    def __init__(self):
        self.steps = []  # List of dicts with keys: name, action, compensate
        self.execution_log = []  # Optional log for compensation errors

    def add_step(self, name, action, compensate):
        """Register a step in the saga.

        Args:
            name (str): Human‑readable identifier for the step; must be non‑empty.
            action (callable): Function that performs the step. Signature ``(context)``.
            compensate (callable): Compensation function to undo the step. Signature ``(context)``.
        """
        if not isinstance(name, str) or not name:
            raise ValueError("Step name must be a non‑empty string")
        if not callable(action):
            raise ValueError("Action must be callable")
        if not callable(compensate):
            raise ValueError("Compensate must be callable")
        self.steps.append({"name": name, "action": action, "compensate": compensate})

    def execute(self, context):
        """Execute all registered steps sequentially.

        If any step raises an exception, previously successful steps are compensated
        in reverse order. A ``SagaExecutionError`` is then raised containing details.
        """
        if not isinstance(context, dict):
            raise ValueError("Context must be a dictionary")

        results = {}
        successful_steps = []  # Keep track of steps that completed successfully
        for step in self.steps:
            try:
                result = step["action"](context)
                results[step["name"]] = result
                successful_steps.append(step)
            except Exception as original_error:
                # Compensation phase – reverse order of successful steps
                compensated = []
                for comp_step in reversed(successful_steps):
                    try:
                        comp_step["compensate"](context)
                        compensated.append(comp_step["name"])
                    except Exception as comp_err:
                        # Log compensation errors but continue compensating remaining steps
                        self.execution_log.append(
                            f"Compensation error in step '{comp_step['name']}': {comp_err}"
                        )
                # Raise a saga‑specific error with full context
                raise SagaExecutionError(step["name"], original_error, compensated) from original_error
        return {"success": True, "results": results}

class InventoryService:
    def __init__(self):
        self.reserved = []

    def reserve(self, item_id):
        # Validate input: non‑empty string, reject booleans
        if not isinstance(item_id, str) or not item_id:
            raise ValueError("item_id must be a non‑empty string")
        if isinstance(item_id, bool):
            raise ValueError("item_id cannot be a boolean")
        self.reserved.append(item_id)
        return f"reserved:{item_id}"

    def cancel(self, item_id):
        if not isinstance(item_id, str) or not item_id:
            raise ValueError("item_id must be a non‑empty string")
        if item_id in self.reserved:
            self.reserved.remove(item_id)

class PaymentService:
    def __init__(self):
        self.charges = []

    def charge(self, amount):
        # Strict numeric validation: reject bool, require int > 0
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("amount must be a positive integer")
        if amount <= 0:
            raise ValueError("amount must be greater than zero")
        if amount > 1000:
            raise ValueError("Credit limit exceeded")
        self.charges.append(amount)
